-- 010_role_templates.sql — the nine initial role templates and their grants.
-- Generated by scripts/gen-rbac-catalogue.py. Administrators can create further
-- templates and edit these; system-role deletion is blocked below.

insert into public.roles (name, description, is_system_role) values
  ('CEO / Managing Partner', 'Full authorised access across company workspaces, executive reporting, financial oversight, user oversight and system governance.', true),
  ('System Administrator', 'User accounts, invitations, suspensions, role and permission management, workspace configuration, security and audit logs, integrations.', true),
  ('Operations Manager', 'Operational workflows, teams, calendars, attendance monitoring, work assignment, operational reports and internal document coordination.', false),
  ('Audit Manager', 'Manages assigned audit engagements, engagement tasks, workpaper review, documents, review stages and engagement reporting.', false),
  ('Senior Auditor', 'Works on assigned engagements, prepares and reviews workpapers, manages tasks and documents, and submits work for manager review.', false),
  ('Audit Associate', 'Access to assigned engagements and tasks, personal task management, workpaper upload, comments, authorised document search and the AI assistant.', false),
  ('Finance Lead', 'Accounting workspaces, journal preparation, reconciliations, periods, financial reporting and delegated approval and posting.', false),
  ('HR / Administration', 'Employee profiles, attendance, leave processing, staff records, onboarding and offboarding and authorised staff reports.', false),
  ('General Staff', 'Personal workspace, tasks, calendar, messaging, announcements, permitted documents, attendance and leave, the AI assistant and team collaboration.', false)
on conflict (name) do update set
  description = excluded.description,
  is_system_role = roles.is_system_role or excluded.is_system_role;

