-- Protect system-critical roles from accidental deletion or deactivation.
create or replace function public.roles_system_guard()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if TG_OP = 'DELETE' then
    if OLD.is_system_role then
      raise exception 'System role % cannot be deleted', OLD.name;
    end if;
    return OLD;
  end if;
  if TG_OP = 'UPDATE' and OLD.is_system_role and NEW.is_system_role = false then
    raise exception 'System role % cannot be demoted', OLD.name;
  end if;
  return NEW;
end;
$$;
drop trigger if exists roles_system_guard on public.roles;
create trigger roles_system_guard before update or delete on public.roles
  for each row execute function public.roles_system_guard();
